head.script:
// 데이터/옵션 분리: JSON 은 순수 데이터만, 아래 type+옵션은 스크립트가 보유 → 렌더시 조합
scwin.CHART_TYPE = "candlestick";                    // 차트 타입 (스크립트)
scwin.CHART_DATA_URL ="/ui/sample/SBChart/CANDLESTICK/data/CANDLESTICK.json";             // 순수 데이터 JSON (type 없음)
scwin.CHART_CONFIG = {
  "tooltip": {   // 툴팁
    "width": "200px"   // 너비(px 또는 비율)
  },
  "axis": {   // 축 설정
    "y": {
      "min": 78000   // 최소값
    }
  },
  "extend": {   // 차트별 세부 옵션
    "candlestick": {   // 캔들스틱 전용 옵션
      "auto": true,
      "marker": {                                              // ★ 고점/저점에 값 마커(삼각형+금액) 표시
        "show": true,
        "color": "#c0392b",
        "min": { "format": function (d) { return "저가 " + d.low.toLocaleString(); } }   // 저점 라벨 포맷
      }
    }
  },
  "dataOpts": {   // 데이터 레벨 옵션(keys/labels 등)
    "keys": {   // 데이터 필드 매핑
      "x": "date",
      "value": [   // 값 필드
        {
          "open": "openprc",   // 시가
          "close": "closeprc",   // 종가
          "low": "lowprc",   // 저가
          "high": "highprc"   // 고가
        }
      ]
    }
  }
};               // 옵션(global/axis/extend…) + dataOpts(keys/labels…)

scwin.onpageload = async function () {
    var res = await $c.sbm.executeDynamic({ id: "sbm_sbchart", action: scwin.CHART_DATA_URL, method: "get", mediatype: "application/json", mode: "asynchronous", isProcessMsg: false });
    var data = res.responseJSON;
    $c.ext.drawChartData(scwin.CHART_TYPE, data, chartWrap, scwin.CHART_CONFIG);
};
